select v.name as vessel,v.flag,b.name as berth,a.arrived_at,a.departed_at,round(extract(epoch from coalesce(a.departed_at,now())-a.arrived_at)/3600,1) as hours from arrivals a join vessels v on v.id=a.vessel_id left join berths b on b.id=a.berth_id where a.arrived_at>=date_trunc('day',now())-interval '7 days' and (v.length_m>120 or v.flag in ('GR','CY','MT')) and not exists(select 1 from inspections i where i.arrival_id=a.id and i.result='held') order by a.arrived_at desc,v.name limit 200;
